import { mkdtemp, readdir, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { setTimeout as delay } from "node:timers/promises";
import { PaneDirection, Server } from "libtmux";

const directory = await mkdtemp(join(tmpdir(), "ltx-home-"));
const server = new Server({
  socketPath: join(directory, "tmux.sock"),
  configFile: "/dev/null",
  timeoutMs: 5_000,
});

const failures: unknown[] = [];
try {
  const signal = AbortSignal.timeout(5_000);
  const session = await server.newSession({ name: "demo", signal });

  // Lay out the session: name its window, split it, add a second window.
  const editor = session.activeWindow;
  if (!editor) throw new Error("The session has no active window");
  await editor.rename("editor");

  const left = editor.activePane;
  if (!left) throw new Error("The window has no active pane");
  const right = await left.split({
    direction: PaneDirection.Right,
    signal,
  });
  const logs = await session.newWindow({ name: "logs", signal });

  // Type a command into the new pane and wait for what it prints.
  await right.sendKeys("printf 'hello from %s\\n' tmux", { signal });

  for (;;) {
    const lines = await right.capture({ signal });
    if (lines.some((line) => line.includes("hello from tmux"))) break;

    await delay(20, undefined, { signal });
  }

  // Move the focus an attached client sees: the pane, then the window.
  await right.select();
  await logs.select();

  // Walk the objects: down from the server, then up from one pane.
  const snapshot = await server.snapshot({ signal });
  for (const each of snapshot.sessions) {
    console.log("session", each.name);
    for (const window of each.windows) {
      const ids = window.panes.map((pane) => pane.id).join(" ");
      console.log(`  window ${window.index}:${window.name}: ${ids}`);
    }
  }

  const pane = snapshot.panes.one({ id: right.id });
  const home = pane.window;
  const owner = pane.session;
  if (!home || !owner) throw new Error("The pane has no window or session");
  console.log(pane.id, "is in window", home.name, "of session", owner.name);
} catch (error) {
  failures.push(error);
}

try {
  if ((await readdir(directory)).includes("tmux.sock")) {
    await server.kill();
  }

  await rm(directory, { recursive: true });
} catch (error) {
  failures.push(new Error(`Cleanup failed: ${directory}`, {
    cause: error,
  }));
}

if (failures.length) throw new AggregateError(failures);

