use libtmux::{PaneWait, Server, SplitDirection, SplitOptions};
use std::{error::Error, time::Duration};

type ExampleError = Box<dyn Error>;

async fn work(server: &Server) -> Result<(), ExampleError> {
    let session = server.new_session("demo").await?;

    // Lay out the session: name its window, split it, add a second window.
    let mut editor =
        session.active_window().await?.ok_or("missing window")?;
    editor.rename("editor").await?;
    let left = editor.active_pane().await?.ok_or("missing pane")?;
    let mut right =
        left.split(SplitOptions::new(SplitDirection::Right)).await?;
    let mut logs = session.new_window("logs").await?;

    // Type a command into the new pane and wait for what it prints.
    right.send_line("printf 'hello from %s\\n' tmux").await?;
    let seen = right
        .wait_for_text("hello from tmux", Duration::from_secs(5))
        .await?;
    if seen != PaneWait::Arrived {
        return Err("The pane did not print hello from tmux".into());
    }

    // Move the focus an attached client sees: the pane, then the window.
    right.select().await?;
    logs.select().await?;

    // Walk the objects: down from the server, then up from one pane.
    let sessions = server.sessions().await?;
    for each in sessions {
        println!("session {}", each.name().to_string_lossy());
        let windows = each.windows().await?;
        for window in windows {
            let name = window.name().to_string_lossy();
            print!("  window {}:{}:", window.index(), name);
            let panes = window.panes().await?;
            for pane in panes {
                print!(" {}", pane.id());
            }
            println!();
        }
    }
    let window = right.window().await?.ok_or("missing window")?;
    let owner = window.session().await?.ok_or("missing session")?;
    println!(
        "{} is in window {} of session {}",
        right.id(),
        window.name().to_string_lossy(),
        owner.name().to_string_lossy(),
    );
    Ok(())
}

#[tokio::main(flavor = "current_thread")]
async fn main() -> Result<(), ExampleError> {
    let root = std::path::Path::new("/tmp/libtmux-rs-dev");
    std::fs::create_dir_all(root)?;
    let directory =
        tempfile::Builder::new().prefix("home-").tempdir_in(root)?;

    let server = Server::builder()
        .socket_path(directory.path().join("tmux.sock"))
        .config_file("/dev/null")
        .default_timeout(Duration::from_secs(5))
        .build()?;

    let outcome =
        tokio::time::timeout(Duration::from_secs(10), work(&server))
            .await;

    // kill stops our daemon; shutdown closes this client executor.
    let killed = server.kill().await;
    let closed = server.shutdown().await;
    let cleanup_failed = killed.is_err() || closed.is_err();

    let mut failures = Vec::new();
    match outcome {
        Ok(Ok(())) => {}
        Ok(Err(error)) => failures.push(format!("work: {error}")),
        Err(error) => failures.push(format!("deadline: {error}")),
    }

    if let Err(error) = killed {
        failures.push(format!("stop owned daemon: {error}"));
    }
    if let Err(error) = closed {
        failures.push(format!("close executor: {error}"));
    }

    if cleanup_failed {
        let retained = directory.keep();
        failures.push(format!("inspect {}", retained.display()));
    } else if let Err(error) = directory.close() {
        failures.push(format!("remove directory: {error}"));
    }

    if failures.is_empty() {
        Ok(())
    } else {
        Err(failures.join("; ").into())
    }
}

