// Command quickstart lays out a tmux session, then walks it as objects.
package main

import (
	"context"
	"errors"
	"fmt"
	"log"
	"os"

	"github.com/libtmux/libtmux-go/tmux"
)

func main() {
	if err := run(context.Background()); err != nil {
		log.Fatal(err)
	}
}

func run(ctx context.Context) (err error) {
	// A private server: a socket and an empty config of its own, so this
	// neither touches nor is changed by a tmux you already use.
	// The process ID in the socket name keeps one run apart from the next.
	server, err := tmux.NewServer(tmux.ServerOptions{
		SocketName: fmt.Sprintf("libtmux-quickstart-%d", os.Getpid()),
		ConfigFile: os.DevNull,
	})
	if err != nil {
		return fmt.Errorf("configure tmux: %w", err)
	}
	session, err := server.NewSession(ctx, tmux.NewSessionRequest{
		Name: "demo",
	})
	if err != nil {
		return fmt.Errorf("create session: %w", err)
	}
	// Cleanup runs even when ctx is the reason the program is leaving.
	defer func() {
		err = errors.Join(err, server.Kill(context.WithoutCancel(ctx)))
	}()

	// Lay out the session: name its window, split it, add a second window.
	editor, err := session.ResolveActiveWindow(ctx)
	if err != nil {
		return fmt.Errorf("find window: %w", err)
	}
	editor, err = editor.Rename(ctx, "editor")
	if err != nil {
		return fmt.Errorf("rename window: %w", err)
	}
	left, err := editor.ResolveActivePane(ctx)
	if err != nil {
		return fmt.Errorf("find pane: %w", err)
	}
	right, err := left.Split(ctx, tmux.SplitPaneRequest{
		Direction: tmux.PaneDirectionRight,
	})
	if err != nil {
		return fmt.Errorf("split pane: %w", err)
	}
	name := "logs"
	logs, err := session.NewWindow(ctx, tmux.NewWindowRequest{
		Name: &name,
	})
	if err != nil {
		return fmt.Errorf("add window: %w", err)
	}

	// Type a command into the new pane and wait for what it prints.
	command := "printf 'hello from %s\\n' tmux"
	err = right.SendKeys(ctx, tmux.SendKeysRequest{Command: &command})
	if err != nil {
		return fmt.Errorf("send keys: %w", err)
	}
	_, err = right.WaitForText(ctx, tmux.WaitForTextRequest{
		Text: "hello from tmux",
	})
	if err != nil {
		return fmt.Errorf("wait for output: %w", err)
	}

	// Move the focus an attached client sees: the pane, then the window.
	_, err = right.Select(ctx, tmux.PaneSelectRequest{})
	if err != nil {
		return fmt.Errorf("select pane: %w", err)
	}
	_, err = logs.Select(ctx)
	if err != nil {
		return fmt.Errorf("select window: %w", err)
	}

	// Walk the objects: down from the server, then up from one pane.
	snapshot, err := server.Snapshot(ctx)
	if err != nil {
		return fmt.Errorf("read tmux: %w", err)
	}
	for _, each := range snapshot.Sessions() {
		sessionName, _ := each.Name()
		fmt.Println("session", sessionName)
		windows, _ := each.Windows()
		for _, window := range windows {
