import io.github.libtmux.Server;
import io.github.libtmux.ServerConfig;
import io.github.libtmux.ServerEndpoint;
import io.github.libtmux.TextOutcome;
import java.nio.file.Path;
import java.time.Duration;
import java.util.UUID;

public final class Main {
    public static void main(String[] args) throws Exception {
        var socket = "libtmux-home-" + UUID.randomUUID();
        var config = ServerConfig.builder()
                .endpoint(ServerEndpoint.namedSocket(socket))
                .configFile(Path.of("/dev/null"))
                .defaultTimeout(Duration.ofSeconds(5))
                .build();

        try (Server server = Server.open(config)) {
            try {
                var session = server.newSession("demo");

                // Lay out the session: name its window, split it, add another.
                var first = session.activeWindow().orElseThrow();
                var editor = first.rename("editor");
                var left = editor.activePane().orElseThrow();
                var right = left.split(spec -> spec.toRight().detached());
                var logs = session.newWindow(
                        spec -> spec.named("logs").detached());

                // Type a command into the new pane and wait for what it prints.
                right.sendLine("printf 'hello from %s\\n' tmux");
                var seen = right.awaitText(
                        "hello from tmux", Duration.ofSeconds(5));
                if (seen == TextOutcome.TIMED_OUT) {
                    throw new IllegalStateException("output did not arrive");
                }

                // Move the focus an attached client sees: pane, then window.
                right.select();
                logs.select();

                // Walk the objects: down from the server, up from one pane.
                var snapshot = server.snapshot();
                var sessions = snapshot.sessions();
                for (var each : sessions) {
                    System.out.println("session " + each.name());
                    var windows = snapshot.windowsOf(each.id());
                    for (var win : windows) {
                        var index = win.context().index();
                        System.out.printf("  window %s:%s:", index, win.name());
                        var panes = snapshot.panesOf(win.context());
                        for (var pane : panes) {
                            System.out.print(" " + pane.id());
                        }
                        System.out.println();
                    }
                }
                var window = right.window();
                var owner = window.session();
                System.out.println(
                        right.id() + " is in window " + window.name()
                                + " of session " + owner.name());
            } catch (Exception error) {
                throw new IllegalStateException(
                        "tmux quickstart failed", error);
            } finally {
                server.killServer();
            }
        }
    }
}

