using System;
using System.Linq;
using System.Threading;
using System.Runtime.Versioning;
using LibTmux;

[assembly: UnsupportedOSPlatform("windows")]

if (OperatingSystem.IsWindows())
{
    throw new PlatformNotSupportedException(
        "This example requires tmux on Unix.");
}

using var deadline = new CancellationTokenSource(
    TimeSpan.FromSeconds(30));
var token = deadline.Token;
// A private server: a socket and an empty config of its own, so this
// neither touches nor is changed by a tmux you already use.
var options = new ServerConnectionOptions
{
    SocketName = "quickstart-" + Guid.NewGuid().ToString("N"),
    ConfigurationFile = "/dev/null",
    TmuxBinaryPath = Environment.GetEnvironmentVariable("LIBTMUX_TMUX")
        ?? "tmux",
};

await using var owned = await Server.CreateOwnedAsync(options, token);
Server server = owned.Value;

try
{
    Session session = await server.CreateSessionAsync(
        new NewSessionRequest { Name = "demo", Command = "/bin/sh" },
        token);

    // Lay out the session: name its window, split it, add a second window.
    // Neither the split nor the new window takes the focus.
    Window editor = (await session.GetWindowsAsync(token))[0];
    editor = await editor.RenameAsync("editor", token);
    Pane left = await editor.GetActivePaneAsync(token);
    Pane right = await left.SplitAsync(
        new SplitPaneRequest
        {
            Direction = PaneDirection.Right,
            Command = "/bin/sh",
        },
        token);
    Window logs = await session.CreateWindowAsync(
        new NewWindowRequest { Name = "logs", Command = "/bin/sh" },
        token);

    // Type a command into the new pane and wait for what it prints.
    await right.SendTextAsync(
        "printf 'hello from %s\\n' tmux",
        cancellationToken: token);
    await TmuxWait.UntilAsync(
        async cancellation => await right.CaptureAsync(
            cancellationToken: cancellation),
        output => output.Any(line => line.Contains("hello from tmux")),
        TimeSpan.FromSeconds(10),
        TimeSpan.FromMilliseconds(20),
        token);

    // Move the focus an attached client sees: the pane, then the window.
    right = await right.SelectAsync(cancellationToken: token);
    logs = await logs.SelectAsync(token);

    // Walk the objects: down from the server, then up from one pane.
    Server snapshot = await server.CaptureSnapshotAsync(
        cancellationToken: token);
    var sessions = snapshot.Sessions;
    foreach (var each in sessions)
    {
        Console.WriteLine("session " + each.Name);
        var windows = each.Windows;
        foreach (var placed in windows)
        {
            var panes = placed.Panes;
            Console.WriteLine(
                $"  window {placed.Index}:{placed.Name}: "
                + string.Join(" ", panes.Select(pane => pane.Id)));
        }
    }
    Pane found = snapshot.Panes.Single(pane => pane.Id == right.Id);
    Window window = found.Window;
    Session owner = window.Session;
    Console.WriteLine(
        $"{found.Id} is in window {window.Name} of session {owner.Name}");
}
catch (Exception error)
{
    throw new InvalidOperationException(
        "tmux quickstart failed", error);
}

