#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <filesystem>
#include <iostream>
#include <stdexcept>
#include <utility>
#include <libtmux/libtmux.hpp>

int main() {
  char directory[] = "/tmp/ltx-cxx-home-XXXXXX";
  if (!mkdtemp(directory)) {
    std::perror("create temporary directory");
    return 1;
  }

  const auto checked = [](auto result) {
    if (!result) throw std::runtime_error(result.error().diagnostic);
    return std::move(result).value();
  };

  const auto socket = std::filesystem::path(directory) / "tmux.sock";
  auto created = libtmux::Server::startable_at_socket_path(
      socket,
      "/dev/null",
      {},
      {.timeout = std::chrono::seconds{5}});
  if (!created) {
    std::fprintf(stderr, "%s\n", created.error().diagnostic.c_str());
    std::filesystem::remove_all(directory);
    return 1;
  }
  const auto server = std::move(created).value();

  const auto work = [&] {
    const auto session = checked(server.new_session({
        .name = "demo",
        .shell_command = "/bin/sh",
    }));

    // Lay out the session: name its window, split it, add a second window.
    const auto editor = checked(session.active_window());
    checked(editor.rename("editor"));
    const auto left = checked(editor.active_pane());
    const auto right = checked(left.split({
        .horizontal = true,
        .shell_command = "/bin/sh",
    }));
    const auto logs = checked(session.new_window({
        .name = "logs",
        .shell_command = "/bin/sh",
    }));

    // Type a command into the new pane and wait for what it prints.
    checked(right.send_line("printf 'hello from %s\\n' tmux"));
    const auto ready = checked(right.wait_for_text(
        "hello from tmux",
        {.timeout = std::chrono::seconds{5}}));
    if (!ready.matched) throw std::runtime_error("output did not arrive");

    // Move the focus an attached client sees: the pane, then the window.
    checked(right.select());
    checked(logs.select());

    // Walk the objects: down from the server, then up from one pane.
    const auto sessions = checked(server.sessions());
    for (const auto& each : sessions) {
      std::cout << "session " << each.name() << '\n';
      const auto windows = checked(each.windows());
      for (const auto& window : windows) {
        std::cout << "  window " << window.index() << ':'
                  << window.name() << ':';
        const auto panes = checked(window.panes());
        for (const auto& pane : panes) {
          std::cout << ' ' << pane.id().value();
        }
        std::cout << '\n';
      }
    }
    const auto window = checked(right.window());
    const auto owner = checked(window.session());
    std::cout << right.id().value() << " is in window " << window.name()
              << " of session " << owner.name() << '\n';
  };

  int status = 0;
  try {
    work();
  } catch (const std::exception& error) {
    std::fprintf(stderr, "%s\n", error.what());
    status = 1;
  }

  if (std::filesystem::exists(socket)) {
    server.kill().value();
  }
  std::filesystem::remove_all(directory);
  return status;
}

