import Foundation
import LibTmux

@main
struct Quickstart {
    static func main() async throws {
        let server = try Server(
            socketName: "libtmux-home-\(UUID().uuidString)",
            configurationFile: "/dev/null"
        )

        do {
            try await work(server)
        } catch {
            print("tmux quickstart failed: \(error)")
            if try await server.isRunning() {
                try await server.killServer()
            }
            throw error
        }
        try await server.killServer()
    }

    static func work(_ server: Server) async throws {
        let session = try await server.newSession(
            named: "demo",
            shell: "/bin/sh"
        )
        let layout = try await server.snapshot()
        guard let editor = layout.windows(of: session).first,
            let left = layout.panes(of: editor).first(where: \.isActive)
        else {
            throw QuickstartError.missing
        }
        try await server.rename(editor, to: "editor")
        let right = try await server.split(
            left,
            direction: .right,
            shell: "/bin/sh"
        )
        let logs = try await server.newWindow(
            in: session,
            named: "logs",
            shell: "/bin/sh"
        )

        try await server.run("printf 'hello from %s\\n' tmux", in: right)
        let ready = try RegexPattern("^hello from tmux$")
        let result = try await server.waitForOutput(
            in: right,
            matching: [ready]
        )
        guard result.outcome == .matched else {
            throw QuickstartError.outputTimedOut
        }

        try await server.select(right)
        try await server.select(logs.link)

        let snapshot = try await server.snapshot()
        for session in snapshot.sessions {
            print("session \(session.name)")
            let windows = snapshot.windows(of: session)
            let links = snapshot.windowLinks(of: session)
            for (window, link) in zip(windows, links) {
                let panes = snapshot.panes(of: window)
                let ids = panes.map { $0.id.rawValue }.joined(separator: " ")
                print("  window \(link.index):\(window.name): \(ids)")
            }
        }

        let home = right.windowID
        guard let window = snapshot.windows.first(where: { $0.id == home }),
            let owner = snapshot.sessions(of: window).first
        else {
            throw QuickstartError.missing
        }
        print("\(right.id.rawValue) is in window \(window.name)"
            + " of session \(owner.name)")
    }

    enum QuickstartError: Error {
        case missing
        case outputTimedOut
    }
}

